<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import type {Task,ToolId,TaskStatus} from '@/domain/types'
import {tools,toolMap,taskStatusLabels} from '@/domain/tools'
import {service} from '@/services/service'
import TaskInfoDialog from '@/components/results/TaskInfoDialog.vue'
import {downloadTask} from '@/components/results/download'
const route=useRoute(),router=useRouter()
const keyword=ref(''),tool=ref<ToolId|''>(''),status=ref<TaskStatus|''>(''),page=ref(1),size=ref(15),items=ref<Task[]>([]),total=ref(0),loading=ref(false),error=ref(''),mode=ref('results'),info=ref<Task|null>(null),showInfo=ref(false),infoLoading=ref(''),exporting=ref('')
const scopedTool=computed(()=>typeof route.params.tool==='string' && route.params.tool in toolMap ? route.params.tool as ToolId : undefined)
const title=computed(()=>scopedTool.value ? `${toolMap[scopedTool.value].name} · 分析记录` : '任务中心')
let controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,version=0
let infoRequest:AbortController|undefined,infoVersion=0
function cancelInfo(){infoVersion++;infoRequest?.abort();infoLoading.value=''}
watch(showInfo,visible=>{if(!visible)cancelInfo()},{flush:'sync'})
watch([scopedTool,page,size,mode],()=>{cancelInfo();showInfo.value=false})
function cancel(){controller?.abort();if(timer)clearTimeout(timer)}
async function load(){cancel();const current=++version;controller=new AbortController();loading.value=true;error.value='';try{const result=await service.listTasks({page:page.value,size:size.value,tool:scopedTool.value || tool.value || undefined,keyword:keyword.value || undefined,status:status.value || undefined},controller.signal);if(current!==version)return;items.value=result.items;total.value=result.total;if(mode.value==='monitor' && items.value.some(t=>['running','queued'].includes(t.status)))timer=setTimeout(()=>void load(),6000)}catch(e){if(current!==version || controller.signal.aborted)return;items.value=[];total.value=0;error.value=e instanceof Error ? e.message : '加载分析记录失败'}finally{if(current===version)loading.value=false}}
function search(){page.value=1;void load()}
watch([scopedTool,page,size],()=>void load(),{immediate:true})
watch(mode,()=>void load())
onBeforeUnmount(()=>{version++;cancel();cancelInfo()})
function view(task:Task){router.push(`/tasks/${encodeURIComponent(task.id)}`)}
async function taskInfo(task:Task){
 showInfo.value=false;cancelInfo();const current=++infoVersion
 const request=new AbortController();infoRequest=request;infoLoading.value=task.id
 try{const result=await service.getTask(task.id,request.signal);if(current!==infoVersion)return;info.value=result;showInfo.value=true}
 catch(e){if(current===infoVersion&&!request.signal.aborted)ElMessage.error(e instanceof Error ? e.message : '加载任务信息失败')}
 finally{if(current===infoVersion)infoLoading.value=''}
}
async function exportData(task:Task){exporting.value=task.id;try{await downloadTask(task,'excel')}catch(e){ElMessage.error(e instanceof Error ? e.message : '导出失败')}finally{exporting.value=''}}
async function manage(task:Task,action:'retry'|'stop'){try{await ElMessageBox.confirm(action==='stop' ? '停止本任务后，已完成的分析结果仍会保留。' : '仅重试本任务中的失败部分，已完成的结果保留。',action==='stop' ? '停止分析' : '重试失败项',{confirmButtonText:'确认',cancelButtonText:'取消'});await (action==='stop' ? service.stopTask(task.id) : service.retryTask(task.id));void load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error ? e.message : '操作失败')}}
function tag(status:TaskStatus):'success'|'warning'|'danger'|'info'|'primary'{return status==='completed' ? 'success' : ['failed','stopped'].includes(status) ? 'danger' : ['partial','awaiting_input'].includes(status) ? 'warning' : ['running','queued'].includes(status) ? 'primary' : 'info'}
</script>
<template><main class="tasks-page"><header class="tasks-heading"><div class="tasks-title"><h1>{{title}}</h1><el-radio-group v-model="mode" aria-label="任务视图"><el-radio-button value="results">分析结果</el-radio-button><el-radio-button value="monitor">运行监控</el-radio-button></el-radio-group></div><el-button v-if="scopedTool" @click="router.push(`/tool/${scopedTool}`)">返回工具</el-button></header><section class="panel tasks-panel"><form class="task-filters" @submit.prevent="search"><el-input v-model="keyword" clearable placeholder="查找任务名称" aria-label="任务名称"/><el-select v-if="!scopedTool" v-model="tool" clearable placeholder="全部工具" aria-label="分析工具" @change="search"><el-option v-for="item in tools" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="status" clearable placeholder="全部状态" aria-label="任务状态" @change="search"><el-option v-for="(label,key) in taskStatusLabels" :key="key" :label="label" :value="key"/></el-select><el-button native-type="submit" :loading="loading">查询</el-button><el-button @click="load">刷新</el-button></form><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="task-error"/><el-table v-loading="loading" height="100%" :data="items" stripe empty-text="暂无分析记录；在工具中添加资料并开始分析后，记录会显示在这里。"><el-table-column prop="name" label="任务名称" min-width="240" show-overflow-tooltip><template #default="{row}"><el-button text type="primary" class="task-name" @click="view(row)">{{row.name}}</el-button></template></el-table-column><el-table-column label="分析工具" min-width="140"><template #default="{row}">{{row.tool ? toolMap[row.tool as ToolId]?.name : '类型待确认'}}</template></el-table-column><el-table-column label="状态" width="125"><template #default="{row}"><el-tag :type="tag(row.status)" effect="light">{{taskStatusLabels[row.status]}}</el-tag></template></el-table-column><el-table-column label="处理情况" min-width="180"><template #default="{row}"><span>{{row.completed}} / {{row.total}} 份</span><span v-if="row.failed" class="failed"> · {{row.failed}} 份失败</span><div v-if="mode==='monitor'" class="muted">{{row.stage || '等待状态更新'}}</div></template></el-table-column><el-table-column prop="createdAt" label="提交时间" min-width="180"/><el-table-column label="操作" :width="mode==='monitor' ? 370 : 295" fixed="right"><template #default="{row}"><div class="task-actions"><el-button text type="primary" :disabled="!row.hasResults && row.status!=='awaiting_input'" @click="view(row)">查看结果</el-button><el-button text type="primary" :loading="infoLoading===row.id" @click="taskInfo(row)">任务信息</el-button><el-button text type="primary" :loading="exporting===row.id" :disabled="!row.hasResults || !row.tool" @click="exportData(row)">导出数据</el-button><template v-if="mode==='monitor'"><el-button v-if="service.capabilities.taskRetry && ['failed','partial'].includes(row.status)" text type="primary" @click="manage(row,'retry')">重试失败项</el-button><el-button v-if="service.capabilities.taskStop && ['running','queued'].includes(row.status)" text type="danger" @click="manage(row,'stop')">停止</el-button></template></div></template></el-table-column></el-table><div class="task-pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[15,30,50]" :total="total" layout="total,sizes,prev,pager,next"/></div></section><p class="tasks-help">查看结果核对分析内容与依据；任务信息查看资料、配置和运行情况；导出数据用于后续整理。</p><TaskInfoDialog v-model="showInfo" :task="info"/></main></template>
<style scoped>

.tasks-page{padding:8px 16px 0;min-width:0;height:100%;display:flex;flex-direction:column;overflow:hidden}.tasks-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:56px;flex:none}.tasks-title{display:flex;align-items:center;gap:18px;flex-wrap:wrap}.tasks-heading h1{font-size:22px;color:#1e3046;margin:0}.tasks-panel{min-height:0;flex:1;display:flex;flex-direction:column;overflow:hidden}.task-filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px 14px;border-bottom:1px solid #e6ebf1;flex:none}.task-filters .el-input{width:240px}.task-filters .el-select{width:160px}.task-error{margin:8px 14px;flex:none}.tasks-panel>.el-table{flex:1;min-height:0}.task-actions{display:flex;gap:4px;align-items:center;flex-wrap:wrap}.task-actions .el-button{padding:6px;font-size:14px;margin:0}.task-name{justify-content:flex-start;padding:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;display:block;font-size:16px}.task-pagination{display:flex;justify-content:flex-end;padding:10px 14px;overflow:auto;border-top:1px solid #e6ebf1;flex:none}.tasks-help{font-size:14px;line-height:1.7;color:#596b80;padding:8px 0;flex:none}.muted{font-size:14px;color:#596b80}.failed{color:#a33e3e}
@media(max-width:700px){.tasks-page{padding:6px 8px 0;overflow:auto}.tasks-heading{padding:8px 4px;gap:10px}.tasks-title{gap:8px}.tasks-heading h1{font-size:18px}.task-filters{padding:10px}.task-filters .el-input{width:100%}.task-filters .el-select{flex:1;min-width:130px}.tasks-title :deep(.el-radio-button__inner){font-size:14px;padding:8px 10px}.tasks-help{font-size:14px}.tasks-panel{min-height:340px;overflow:hidden}}
</style>
